class Solution { public:vector<string> findHighAccessEmployees(vector<vector<string>>& access_times){map<string,vector<int>> times;for(auto& access:access_times){string value=access[1];int minute=stoi(value.substr(0,2))*60+stoi(value.substr(2));times[access[0]].push_back(minute);}vector<string> answer;for(auto& [name,values]:times){sort(values.begin(),values.end());for(int i=2;i<(int)values.size();++i)if(values[i]-values[i-2]<60){answer.push_back(name);break;}}return answer;} };
